"""On-the-fly data: problems are generated by CPU workers, so nothing is
downloaded or stored on disk (the 40 GB storage limit only applies to
checkpoints and results)."""

import random

from torch.utils.data import DataLoader, IterableDataset, get_worker_info

from .examples import correct_example, plain_example
from .igsm.checker import analyze
from .igsm.generator import GenConfig, generate_problem
from .igsm.tokenizer import Tokenizer


class CorrectStream(IterableDataset):
    """Yields lists of `n` examples built from freshly generated correct solutions."""

    def __init__(self, cfg, stage, n, seed):
        self.cfg, self.stage, self.n, self.seed = cfg, stage, n, seed

    def __iter__(self):
        wi = get_worker_info()
        wid = wi.id if wi is not None else 0
        rng = random.Random(self.seed * 1000 + wid)
        tok = Tokenizer()
        g = GenConfig.from_dict(self.cfg["data"]["gen"])
        op = tuple(self.cfg["data"]["op_train"])
        rcfg = self.cfg["revision"]
        t = self.cfg["train"]
        K = t["windows_per_seq"]
        while True:
            exs = []
            for _ in range(self.n):
                prob = generate_problem(rng, g, op, tok)
                if self.stage == "plain":
                    exs.append(plain_example(prob))
                else:
                    a = analyze(prob, prob.solution_ids, tok)
                    n_masked = sum(rng.random() < t["masked_window_prob"] for _ in range(K))
                    exs.append(correct_example(prob, a, rng, tok, rcfg, K - n_masked, n_masked))
            yield exs


def make_loader(cfg, stage, n, seed, num_workers):
    ds = CorrectStream(cfg, stage, n, seed)
    return DataLoader(ds, batch_size=None, num_workers=num_workers, persistent_workers=num_workers > 0,
                      prefetch_factor=4 if num_workers > 0 else None)
